import type { CapabilityContext } from "@/capabilities/shared/context";
import type { SessionNativeMethods } from "./native";
import { normalizePasswordData } from "./normalizers";
import { validateDeviceId, validateConnectOptions, validateDeviceName, validateConnectionConfirmTimeout } from "./validators";
import type {
  ConnectOptions,
  ConnectionStatus,
  OperationStatus,
  PasswordData,
  RestorationState,
} from "@/types/index";

export class SessionCapability {
  constructor(private readonly ctx: CapabilityContext<SessionNativeMethods>) {}

  async connect(deviceId: string, options?: ConnectOptions): Promise<void> {
    validateDeviceId(deviceId);
    if (options) validateConnectOptions(options);
    this.ctx.log("info", "connection", "connect.start", "Connecting device", { deviceId, data: options });
    return this.ctx.invoke({
      invoke: () => this.ctx.native.connect(deviceId, options),
      errorCode: "CONNECTION_FAILED",
      errorDeviceId: deviceId,
      afterSuccess: () => {
        this.ctx.setConnectedDeviceId(deviceId);
        this.ctx.log("info", "connection", "connect.success", "Device connect request completed", { deviceId });
      },
    });
  }

  async disconnect(deviceId?: string): Promise<void> {
    const id = deviceId || this.ctx.connectedDeviceId();
    if (!id) return;

    this.ctx.log("info", "connection", "disconnect.start", "Disconnecting device", { deviceId: id });
    return this.ctx.invoke({
      invoke: () => this.ctx.native.disconnect(id),
      errorCode: "DISCONNECTION_FAILED",
      errorDeviceId: id,
      afterSuccess: () => {
        if (this.ctx.connectedDeviceId() === id) {
          this.ctx.setConnectedDeviceId(null);
        }
        this.ctx.log("info", "connection", "disconnect.success", "Device disconnected", { deviceId: id });
      },
    });
  }

  /**
   * [RESTORATION] Whether iOS armed CoreBluetooth state restoration, and whether
   * this launch was one iOS started to resume BLE work. Never throws — a failure
   * to read it must not block session start, so it degrades to "unsupported".
   */
  async getRestorationState(): Promise<RestorationState> {
    return this.ctx.invokeWithRecovery({
      invoke: () => this.ctx.native.getRestorationState(),
      errorCode: "UNKNOWN",
      recoverWith: { supported: false, restoration_launch: false, armed: false },
    });
  }

  async getConnectionStatus(deviceId?: string): Promise<ConnectionStatus> {
    const id = deviceId || this.ctx.connectedDeviceId();
    if (!id) return "disconnected";

    return this.ctx.invokeWithRecovery({
      invoke: () => this.ctx.native.getConnectionStatus(id),
      errorCode: "UNKNOWN",
      errorDeviceId: id,
      recoverWith: "disconnected",
      afterSuccess: (status: ConnectionStatus) => {
        this.ctx.log("debug", "connection", "connection.status", "Fetched connection status", {
          deviceId: id,
          data: { status },
        });
      },
    });
  }

  async verifyPassword(password: string = "0000", is24Hour: boolean = false): Promise<PasswordData> {
    this.ctx.log("info", "connection", "password.verify.start", "Verifying device password", {
      data: { is24Hour },
    });
    return this.ctx.invoke({
      invoke: () => this.ctx.native.verifyPassword(password, is24Hour),
      normalize: normalizePasswordData,
      afterSuccess: (result: PasswordData) => {
        this.ctx.log("info", "connection", "password.verify.result", "Device password verified", {
          data: {
            status: result.status,
            device_number: result.device_number,
            device_version: result.device_version,
          },
        });
      },
    });
  }

  renameDevice(name: string): Promise<OperationStatus> {
    return this.ctx.invoke({
      validate: () => validateDeviceName(name),
      invoke: () => this.ctx.native.renameDevice(name),
    });
  }

  isConnectionConfirmEnabled(): Promise<boolean> {
    return this.ctx.invoke({
      invoke: () => this.ctx.native.isConnectionConfirmEnabled(),
    });
  }

  setConnectionConfirmEnabled(enabled: boolean): Promise<OperationStatus> {
    return this.ctx.invoke({
      invoke: () => this.ctx.native.setConnectionConfirmEnabled(enabled),
    });
  }

  setConnectionConfirmTimeout(seconds: number): Promise<OperationStatus> {
    return this.ctx.invoke({
      validate: () => validateConnectionConfirmTimeout(seconds),
      invoke: () => this.ctx.native.setConnectionConfirmTimeout(seconds),
    });
  }
}
